200	int exec_spawn(FAR const char *filename, FAR char * const *argv,
201	               FAR char * const *envp, FAR const struct symtab_s *exports,
202	               int nexports, FAR const posix_spawn_file_actions_t *actions,
203	               FAR const posix_spawnattr_t *attr)
